import days from "@/data/funding/days.json";
import {
  STREAM_IDS,
  ZAT_PER_ZEC,
  allocationBetween,
  type Allocation,
  type StreamId,
} from "./consensus";

/**
 * Daily series of every non-miner allocation since genesis. The only inputs
 * are the day's height range and closing price (src/data/funding/days.json,
 * regenerated by scripts/gen-funding-history.ts); amounts come from the
 * consensus rules. "USD at receipt" values each day's ZEC at that day's close.
 */

type DayRow = [
  date: string,
  fromHeight: number,
  toHeight: number,
  closeUsd: number | null,
];

type DaysDoc = {
  version: number;
  generatedAt: string;
  through: { date: string; height: number };
  sources: { heights: string; prices: string; note: string };
  rows: DayRow[];
};

const DOC = days as unknown as DaysDoc;

export type DayPoint = {
  date: string;
  fromHeight: number;
  toHeight: number;
  closeUsd: number | null;
  allocation: Allocation;
};

export type StreamTotal = {
  id: StreamId;
  zat: number;
  /** Sum over days of ZEC received × that day's close. */
  usdAtReceipt: number;
  /** ZEC received on days without a market close (genesis day only). */
  zatWithoutPrice: number;
  firstDate: string | null;
  lastDate: string | null;
};

export type YearTotal = {
  year: string;
  zat: Record<StreamId, number>;
  usd: Record<StreamId, number>;
  subsidyZat: number;
};

export const HISTORY_META = {
  generatedAt: DOC.generatedAt,
  through: DOC.through,
  sources: DOC.sources,
};

let series: DayPoint[] | null = null;

/** One point per complete UTC day, genesis first. Computed once per process. */
export function dailySeries(): DayPoint[] {
  if (!series) {
    series = DOC.rows.map(([date, fromHeight, toHeight, closeUsd]) => ({
      date,
      fromHeight,
      toHeight,
      closeUsd,
      allocation: allocationBetween(fromHeight, toHeight),
    }));
  }
  return series;
}

const zeroByStream = (): Record<StreamId, number> =>
  Object.fromEntries(STREAM_IDS.map((id) => [id, 0])) as Record<
    StreamId,
    number
  >;

export function streamTotals(
  points: DayPoint[] = dailySeries(),
): StreamTotal[] {
  return STREAM_IDS.map((id) => {
    const t: StreamTotal = {
      id,
      zat: 0,
      usdAtReceipt: 0,
      zatWithoutPrice: 0,
      firstDate: null,
      lastDate: null,
    };
    for (const p of points) {
      const zat = p.allocation[id];
      if (zat === 0) continue;
      t.zat += zat;
      if (p.closeUsd === null) t.zatWithoutPrice += zat;
      else t.usdAtReceipt += (zat / ZAT_PER_ZEC) * p.closeUsd;
      t.firstDate ??= p.date;
      t.lastDate = p.date;
    }
    return t;
  });
}

export function yearlyTotals(points: DayPoint[] = dailySeries()): YearTotal[] {
  const byYear = new Map<string, YearTotal>();
  for (const p of points) {
    const year = p.date.slice(0, 4);
    const y = byYear.get(year) ?? {
      year,
      zat: zeroByStream(),
      usd: zeroByStream(),
      subsidyZat: 0,
    };
    y.subsidyZat += p.allocation.subsidy;
    for (const id of STREAM_IDS) {
      const zat = p.allocation[id];
      y.zat[id] += zat;
      if (p.closeUsd !== null) y.usd[id] += (zat / ZAT_PER_ZEC) * p.closeUsd;
    }
    byYear.set(year, y);
  }
  return [...byYear.values()];
}

/** Everything the protocol issued up to the last complete day, by recipient. */
export function issuedThrough(points: DayPoint[] = dailySeries()): Allocation {
  const last = points[points.length - 1];
  return allocationBetween(0, last.toHeight);
}

/** CSV of the daily series, one column per stream in ZEC plus the close. */
export function seriesCsv(points: DayPoint[] = dailySeries()): string {
  const header = [
    "date",
    "from_height",
    "to_height",
    "close_usd",
    ...STREAM_IDS.map((id) => `${id}_zec`),
    "miner_zec",
  ];
  const zec = (zat: number) => (zat / ZAT_PER_ZEC).toFixed(8);
  const lines = points.map((p) =>
    [
      p.date,
      p.fromHeight,
      p.toHeight,
      p.closeUsd ?? "",
      ...STREAM_IDS.map((id) => zec(p.allocation[id])),
      zec(p.allocation.miner),
    ].join(","),
  );
  return [header.join(","), ...lines].join("\n") + "\n";
}

/** The UTC day a block height falls in, from the daily series; null past its end. */
export function dateOfHeight(height: number, points: DayPoint[] = dailySeries()): string | null {
  let lo = 0;
  let hi = points.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const p = points[mid];
    if (height < p.fromHeight) hi = mid - 1;
    else if (height > p.toHeight) lo = mid + 1;
    else return p.date;
  }
  return null;
}
